"""clinicdb: reports over the clinic network database."""


def latest_visit_per_clinic(conn):
    """The most recent visit of every clinic."""
    out = []
    for owner_id, name in conn.execute("SELECT id, name FROM clinics ORDER BY name").fetchall():
        row = conn.execute(
            "SELECT reason FROM visits WHERE clinic_id = ? ORDER BY seen_on DESC, id DESC LIMIT 1", (owner_id,)
        ).fetchone()
        out.append((name, row[0] if row else None))
    return out

