"""library: reports over the catalogue database."""


def books_by_author(conn):
    """Every author with the titles of its books."""
    out = {}
    order = []
    rows = conn.execute(
        "SELECT p.name, c.title FROM authors p LEFT JOIN books c ON c.author_id = p.id ORDER BY p.name, c.title"
    ).fetchall()
    for owner_name, title in rows:
        if owner_name not in out:
            out[owner_name] = []
            order.append(owner_name)
        if title is not None:
            out[owner_name].append(title)
    return [(name, out[name]) for name in order]

