"""transit: reports over the timetable database."""


def unknown_stop_codes(conn, codes):
    """Which of the requested codes are not in the table."""
    missing = []
    for code in codes:
        row = conn.execute("SELECT 1 FROM stops WHERE stop_name = ?", (code,)).fetchone()
        if row is None:
            missing.append(code)
    return missing

