"""labtrack: reports over the sample tracker database."""


def samples_by_lab(conn):
    """Every lab with the titles of its samples."""
    out = {}
    order = []
    rows = conn.execute(
        "SELECT p.name, c.label FROM labs p LEFT JOIN samples c ON c.lab_id = p.id ORDER BY p.name, c.label"
    ).fetchall()
    for owner_name, title in rows:
        if owner_name not in out:
            out[owner_name] = []
            order.append(owner_name)
        if title is not None:
            out[owner_name].append(title)
    return [(name, out[name]) for name in order]

