"""taskboard: reports over the project board database."""


def unknown_task_codes(conn, codes):
    """Which of the requested codes are not in the table."""
    missing = []
    for code in codes:
        row = conn.execute("SELECT 1 FROM tasks WHERE summary = ?", (code,)).fetchone()
        if row is None:
            missing.append(code)
    return missing
